// 5 codes ROME couvrant les métiers systèmes, réseaux et support.
// Volumes constatés le 30/09/2026 à 60 km de Toulouse : 74, 78, 66, 15, 15.
const ROMES = [
  { code: 'M1801', libelle: 'Administration de systèmes d\'information' },
  { code: 'M1802', libelle: 'Expertise et support en systèmes d\'information' },
  { code: 'M1805', libelle: 'Études et développement informatique' },
  { code: 'M1810', libelle: 'Production et exploitation de systèmes d\'information' },
  { code: 'I1401', libelle: 'Maintenance informatique et bureautique' },
];
const CITYCODE = '31555';   // Toulouse
const DISTANCE = 60;        // km
return ROMES.map(r => ({ json: { ...r, citycode: CITYCODE, distance: DISTANCE } }));

// Un même établissement peut remonter sur plusieurs codes ROME : on garde
// celui qui a le meilleur potentiel d'embauche.
const parSiret = new Map();
let enEchec = 0;
for (const item of $input.all()) {
  // Un code ROME en échec (onError: continueRegularOutput) ressort sans `items` : on le signale et on continue.
  if (!Array.isArray(item.json.items)) { enEchec++; continue; }
  for (const e of item.json.items) {
    if (!e.siret) continue;
    const existant = parSiret.get(e.siret);
    const potentiel = Number(e.hiring_potential) || 0;
    if (existant && existant.potentiel >= potentiel) {
      if (!existant.romes.includes(e.rome)) existant.romes.push(e.rome);
      continue;
    }
    parSiret.set(e.siret, {
      siret: e.siret,
      nom: e.company_name || '',
      ville: e.city || '',
      citycode: e.citycode || '',
      lat: e.location?.lat ?? null,
      lon: e.location?.lon ?? null,
      effectif: [e.headcount_min, e.headcount_max].filter(v => v !== null && v !== undefined).join('-'),
      naf_label: e.naf_label || '',
      potentiel: Math.round(potentiel * 10) / 10,
      romes: existant ? [...existant.romes, e.rome] : [e.rome],
    });
  }
}
console.log(`${parSiret.size} établissements distincts — ${enEchec} code(s) ROME en échec sur ${$input.all().length}`);
return [...parSiret.values()].map(json => ({ json }));

// Clés déjà présentes dans Notion : SIRET (clé forte) et noms (clé de repli).
// Les lignes saisies à la main n'ont pas de SIRET : le nom est alors la seule clé qui les protège.
const pages = [];
const reponses = $input.all();
// Garde-fous : une lecture Notion illisible ou incomplète ne doit JAMAIS passer pour « base vide »,
// sinon les 88 entreprises ressortiraient comme nouvelles.
if (!reponses.length || reponses.some(r => !Array.isArray(r.json.results))) {
  throw new Error('Lecture Notion invalide : pas de champ results');
}
if (reponses[reponses.length - 1].json.has_more) {
  throw new Error('Lecture Notion incomplète : has_more encore vrai (plafond de pages atteint)');
}
for (const r of reponses) pages.push(...r.json.results);
// Une propriété renommée viderait silencieusement une des deux clés.
if (pages.length && (!pages[0].properties?.SIRET || !pages[0].properties?.Entreprise)) {
  throw new Error('Propriété SIRET ou Entreprise introuvable dans la base Notion');
}
const sirets = new Set();
const noms = new Set();
for (const page of pages) {
  const p = page.properties;
  const siret = (p.SIRET.rich_text || []).map(t => t.plain_text).join('').replace(/\D/g, '');
  if (siret) sirets.add(siret);
  const nom = (p.Entreprise.title || []).map(t => t.plain_text).join('').trim();
  if (nom) noms.add(nom);
}
console.log(`Notion : ${pages.length} ligne(s), ${sirets.size} SIRET, ${noms.size} nom(s)`);
return [{ json: { lignes: pages.length, sirets: [...sirets], noms: [...noms] } }];

// Normalisation des raisons sociales : clé de repli quand le SIRET manque.
// « IWIT Systems », « IWIT SYSTEMS SAS » et « iwit-systems » donnent la même clé.
const FORMES = /\b(SAS|SASU|SARL|EURL|SA|SCOP|SCI|SNC|GIE|EI|EIRL|GROUP|GROUPE|FRANCE)\b/g;
const normNom = s => String(s || '')
  .toUpperCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // enlève les accents
  .replace(FORMES, '')
  .replace(/[^A-Z0-9]/g, '');
const normSiret = s => String(s || '').replace(/\D/g, '');

const connu = $('Clés connues').first().json;
const sirets = new Set(connu.sirets);
const noms = new Set(connu.noms.map(normNom).filter(Boolean));

const tous = $('Dédoublonner').all();
let parSiret = 0;
let parNom = 0;
const nouveaux = tous.filter(i => {
  const s = normSiret(i.json.siret);
  const n = normNom(i.json.nom);
  if (s && sirets.has(s)) { parSiret++; return false; }   // clé forte
  if (n && noms.has(n)) { parNom++; return false; }       // clé de repli
  return true;
});
console.log(`${nouveaux.length} nouvelles sur ${tous.length} — ${parSiret} connues par SIRET, ${parNom} par nom`);
return nouveaux;

// Fusionne la réponse du registre avec l'établissement d'origine.
// Un SIRET introuvable ou une erreur réseau (onError: continueRegularOutput) ne plante rien :
// l'entreprise ressort avec registre = 'introuvable' / 'erreur' et sera écartée par le filtre suivant.
const base = $('Filtrer les nouvelles').item.json;
const r = ($json.results || [])[0];
let registre = 'ok';
if ($json.error) registre = 'erreur';
else if (!r) registre = 'introuvable';

// L'établissement (SIRET de La Bonne Boîte) doit être celui que le registre a trouvé,
// et c'est SON état qui compte : une société peut rester active alors que cet établissement est fermé.
const etab = (r?.matching_etablissements || []).find(e => e.siret === base.siret);
if (registre === 'ok' && !etab) registre = 'introuvable';

const dirigeants = ((r && r.dirigeants) || [])
  .filter(d => d.type_dirigeant === 'personne physique')
  .map(d => `${(d.prenoms || '').trim()} ${(d.nom || '').trim()}${d.qualite ? ' — ' + d.qualite : ''}`)
  .slice(0, 4)
  .join(' · ');

// 'A' seulement si la société ET l'établissement sont actifs ; sinon l'état qui pose problème.
const etat = registre === 'ok'
  ? (etab.etat_administratif !== 'A' ? etab.etat_administratif : r.etat_administratif)
  : '';

return { json: {
  ...base,
  registre,
  dirigeants,
  date_creation: r?.date_creation || '',
  etat_administratif: etat,
  effectif_registre: r?.tranche_effectif_salarie || '',
} };
